class SeedDict(TypedDict):
    """A reference to a catalog record used as a list seed."""

    key: str


SeedSubjectString = NewType("SeedSubjectString", str)
SeedInput: TypeAlias = Thing | SeedDict | SeedSubjectString | str
StoredSeed: TypeAlias = SeedInput | web.storage

_SUBJECT_SEED_PREFIXES = ("subject:", "place:", "person:", "time:")


def _is_seed_subject_string(seed: str) -> TypeGuard[SeedSubjectString]:
    return seed.startswith(_SUBJECT_SEED_PREFIXES)


def _subject_key_to_seed(key: str) -> SeedSubjectString:
    key = key.rsplit("/", 1)[-1]
    if not _is_seed_subject_string(key):
        key = f"subject:{key}"
    return SeedSubjectString(key.replace(",", "_").replace("__", "_"))


def _seed_key(seed: StoredSeed) -> str:
    if isinstance(seed, Thing):
        return seed.key
    if isinstance(seed, str):
        return str(_subject_key_to_seed(seed))
    if isinstance(seed, dict):
        return seed["key"]
    return seed.key


def _normalize_seed(seed: StoredSeed) -> SeedDict | SeedSubjectString:
    if isinstance(seed, Thing):
        key = seed.key
    elif isinstance(seed, str):
        if seed.startswith("/subjects/") or _is_seed_subject_string(seed):
            return _subject_key_to_seed(seed)
        return {"key": seed}
    elif isinstance(seed, dict):
        key = seed["key"]
    else:
        key = seed.key

    if key.startswith("/subjects/") or _is_seed_subject_string(key):
        return _subject_key_to_seed(key)
    return {"key": key}


class ExportList(TypedDict):
    authors: list[dict[str, Any]]
    works: list[dict[str, Any]]
    editions: list[dict[str, Any]]


class List(Thing):
    """Class to represent /type/list objects in OL.

    List contains the following properties:

        * name - name of the list
        * description - detailed description of the list (markdown)
        * members - members of the list. Either references or subject strings.
        * cover - id of the book cover. Picked from one of its editions.
        * tags - list of tags to describe this list.
    """

    def url(self, suffix: str = "", **params: Any) -> str:
        return self.get_url(suffix, **params)

    def get_url_suffix(self) -> str:
        return self.name or "unnamed"

    def get_owner(self) -> Thing | None:
        if match := web.re_compile(r"(/people/[^/]+)/lists/OL\d+L").match(self.key):
            key = match.group(1)
            return self._site.get(key)

    def get_cover(self) -> Image | None:
        """Returns a cover object."""
        return self.cover and Image(self._site, "b", self.cover)

    def get_tags(self) -> list[web.storage]:
        """Returns tags as objects.

        Each tag object will contain name and url fields.
        """
        return [web.storage(name=t, url=self.key + "/tags/" + t) for t in self.tags]

    def _get_subjects(self) -> list[web.storage]:
        """Returns list of subjects inferred from the seeds.
        Each item in the list will be a storage object with title and url.
        """
        # sample subjects
        return [
            web.storage(title="Cheese", url="/subjects/cheese"),
            web.storage(title="San Francisco", url="/subjects/place:san_francisco"),
        ]

    def add_seed(self, seed: SeedInput) -> bool:
        """Adds a new seed to this list.

        seed can be:
            - author, edition or work object
            - {"key": "..."} for author, edition or work objects
            - subject strings.
        """
        normalized_seed = _normalize_seed(seed)
        if self._index_of_seed(seed) >= 0:
            return False
        self.seeds = self.seeds or []
        self.seeds.append(normalized_seed)
        return True

    def remove_seed(self, seed: SeedInput) -> bool:
        """Removes a seed for the list."""
        if (index := self._index_of_seed(seed)) >= 0:
            self.seeds.pop(index)
            return True
        return False

    def _index_of_seed(self, seed: SeedInput) -> int:
        seed_key = str(_seed_subject_key(seed))
        for i, stored_seed in enumerate(self.seeds or []):
            if _seed_comparison_key(stored_seed) == seed_key:
                return i
        return -1

    def __repr__(self) -> str:
        return f"<List: {self.key} ({self.name!r})>"

    def _get_rawseeds(self) -> list[str]:
        return [_seed_comparison_key(seed) for seed in self.seeds or []]

    @cached_property
    def last_update(self) -> datetime | None:
        last_updates = [seed.last_update for seed in self.get_seeds()]
        last_updates = [x for x in last_updates if x]
        if last_updates:
            return max(last_updates)
        else:
            return None

    @property
    def seed_count(self) -> int:
        return len(self.seeds)

    def preview(self) -> dict[str, str | int | None]:
        """Return data to preview this list.

        Used in the API.
        """
        return {
            "url": self.key,
            "full_url": self.url(),
            "name": self.name or "",
            "seed_count": self.seed_count,
            "last_update": self.last_update and self.last_update.isoformat() or None,
        }

    def get_book_keys(self, offset: int = 0, limit: int = 50) -> list[str]:
        offset = offset or 0
        book_keys = set()
        for seed in self.get_seeds():
            if seed.key.startswith(("/books", "/works")):
                works = getattr(seed.document, "works", [])
                book_keys.add(works[0].key if works else seed.key)
        return list(book_keys)[offset : offset + limit]

    def get_editions(
        self, limit: int = 50, offset: int = 0, _raw: bool = False
    ) -> dict[str, Any]:
        """Returns the editions objects belonged to this list ordered by last_modified.

        When _raw=True, the edtion dicts are returned instead of edtion objects.
        """
        edition_keys = {
            seed.key for seed in self.get_seeds() if seed.type == "edition"
        }

        editions = web.ctx.site.get_many(list(edition_keys))

        return {
            "count": len(editions),
            "offset": offset,
            "limit": limit,
            "editions": editions,
        }
        # TODO
        # We should be able to get the editions from solr and return that.
        # Might be an issue of the total number of editions is too big, but
        # that isn't the case for most lists.

    def get_all_editions(self) -> list[dict[str, Any]]:
        """Returns all the editions of this list in arbitrary order.

        The return value is an iterator over all the editions. Each entry is a dictionary.
        (Compare the difference with get_editions.)

        This works even for lists with too many seeds as it doesn't try to
        return editions in the order of last-modified.
        """
        def get_query_term(seed: Seed) -> str | None:
            if seed.type == "work":
                return "key:%s" % seed.key.split("/")[-1]
            if seed.type == "author":
                return "author_key:%s" % seed.key.split("/")[-1]

        seeds = self.get_seeds()
        query_terms = [get_query_term(seed) for seed in seeds]
        query_terms = [q for q in query_terms if q]  # drop Nones
        edition_keys = set(self._get_edition_keys_from_solr(query_terms))

        # Add all editions
        edition_keys.update(
            seed.key for seed in seeds if seed.type == "edition"
        )

        return [doc.dict() for doc in web.ctx.site.get_many(list(edition_keys))]

    def _get_edition_keys_from_solr(self, query_terms: list[str]) -> Iterable[str]:
        if not query_terms:
            return
        q = " OR ".join(query_terms)
        solr = get_solr()
        result = solr.select(q, fields=["edition_key"], rows=10000)
        for doc in result['docs']:
            if 'edition_key' not in doc:
                continue
            for k in doc['edition_key']:
                yield "/books/" + k

    def get_export_list(self) -> ExportList:
        """Returns all the editions, works and authors of this list in arbitrary order.

        The return value is an iterator over all the entries. Each entry is a dictionary.

        This works even for lists with too many seeds as it doesn't try to
        return entries in the order of last-modified.
        """

        keys_by_type = {"editions": set(), "works": set(), "authors": set()}
        type_paths = {
            "/type/edition": "editions",
            "/type/work": "works",
            "/type/author": "authors",
        }
        key_prefixes = {
            "editions": "/books/",
            "works": "/works/",
            "authors": "/authors/",
        }

        for seed in self.seeds or []:
            normalized_seed = _normalize_seed(seed)
            if isinstance(normalized_seed, str):
                continue
            key = normalized_seed["key"]
            for type_key, export_type in type_paths.items():
                if key.startswith(key_prefixes[export_type]):
                    keys_by_type[export_type].add(key)
                    break

        export_list: ExportList = {"authors": [], "works": [], "editions": []}
        for export_type, expected_type in type_paths.items():
            docs = self._site.get_many(sorted(keys_by_type[export_type]))
            export_list[export_type] = [
                doc.dict()
                for doc in docs
                if doc is not None and doc.type.key == expected_type
            ]
        return export_list

    def _preload(self, keys: Iterable[str]) -> list[Thing]:
        keys = list(set(keys))
        return self._site.get_many(keys)

    def preload_works(self, editions: Iterable[dict[str, Any]]) -> list[Thing]:
        return self._preload(w.key for e in editions for w in e.get('works', []))

    def preload_authors(self, editions: Iterable[dict[str, Any]]) -> list[Thing]:
        works = self.preload_works(editions)
        return self._preload(
            a.author.key for w in works for a in w.get("authors", []) if "author" in a
        )

    def load_changesets(self, editions: Iterable[Thing]) -> None:
        """Adds "recent_changeset" to each edition.

        The recent_changeset will be of the form:
            {
                "id": "...",
                "author": {
                    "key": "..",
                    "displayname", "..."
                },
                "timestamp": "...",
                "ip": "...",
                "comment": "..."
            }
        """
        for e in editions:
            if "recent_changeset" not in e:
                with contextlib.suppress(IndexError):
                    e['recent_changeset'] = self._site.recentchanges(
                        {"key": e.key, "limit": 1}
                    )[0]

    def _get_solr_query_for_subjects(self) -> str:
        terms = [seed.get_solr_query_term() for seed in self.get_seeds()]
