        self, sort: bool = False, resolve_redirects: bool = False
    ) -> list[Seed]:
        seeds: list[Seed] = []
        for value in self.seeds or []:
            normalized_seed = _normalize_seed(value)
            if isinstance(normalized_seed, str):
                seed = Seed(self, normalized_seed)
            else:
                document = self._site.get(normalized_seed["key"])
                seed = Seed(self, document or normalized_seed)
            max_checks = 10
            while resolve_redirects and seed.type == 'redirect' and max_checks:
                seed = Seed(self, web.ctx.site.get(seed.document.location))
                max_checks -= 1
            seeds.append(seed)

        if sort:
            seeds = h.safesort(seeds, reverse=True, key=lambda seed: seed.last_update)

        return seeds

